// Single runnable file with multiple top-level package-private classes.
package com.bank.capture;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;

public class CaptureDemo {
    private static final Logger log = Logger.getLogger(CaptureDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<TransferRequest> batch = List.of(
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000")),
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("30000")),
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("20000")));
        BatchTransferProcessor processor = new BatchTransferProcessor();
        processor.process(batch);
    }
}

// ─── Would be in model/TransferRequest.java ───
class TransferRequest {
    private final String from;
    private final String to;
    private final BigDecimal amount;
    TransferRequest(String from, String to, BigDecimal amount) {
            this.from = from;
            this.to = to
            this.amount = amount;
    }
    String getFrom() { return from; }
    String getTo() { return to; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in callback/TransferCallback.java ───
interface TransferCallback {
    void onResult(boolean success);
}

// ─── Would be in service/BatchTransferProcessor.java ───
class BatchTransferProcessor {
    private static final Logger log = Logger.getLogger(BatchTransferProcessor.class.getName());

    void process(List<TransferRequest> batch) {
        // Mutable holder: the REFERENCE is effectively final, but the OBJECT
        // it points to can be updated from inside anonymous callbacks.
        AtomicInteger successCount = new AtomicInteger(0);
        List<TransferCallback> pending = new ArrayList<>();
        int index = 0;

        for (TransferRequest req : batch) {
            // Per-iteration EFFECTIVELY-FINAL locals captured by the callback.
            // `reference` and `amount` are assigned once and never reassigned.
            final String reference = "TXF-" + (++index);
            BigDecimal amount = req.getAmount();   // effectively final (never reassigned)

            // WRONG (would NOT compile): reassigning a captured local.
            // int localCount = 0;
            // TransferCallback bad = success -> { localCount++; };  // ERROR: must be final
            // Fix: use AtomicInteger (done above with successCount).

            TransferCallback cb = new TransferCallback() {
                @Override public void onResult(boolean success) {
                    // Reads the CAPTURED COPY of reference and amount — stable snapshot.
                    if (success) {
                        int now = successCount.incrementAndGet();  // mutate shared holder
                        log.info(() -> "DONE ref=" + reference + " amount Rs." + amount
                                + " successCount=" + now);
                    } else {
                        log.severe(() -> "FAILED ref=" + reference + " amount Rs." + amount);
                    }
                }
            };
            pending.add(cb);
        }

        // Later execution: method already prepared all callbacks; each still
        // sees its own captured reference and amount even though the loop ended.
        boolean[] outcomes = {true, true, false};
        for (int i = 0; i < pending.size(); i++) {
            pending.get(i).onResult(outcomes[i]);
        }
        log.info(() -> "Batch complete. Total succeeded = " + successCount.get());
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
